static final Set<String> TRUSTED = Set.of("10.0.1.5", "10.0.2.7");

static String clientIp(String remoteAddr, String xff) {
    List<String> hops = new ArrayList<>(Arrays.asList(xff.split("\\s*,\\s*")));
    hops.add(remoteAddr);
    for (int i = hops.size() - 1; i >= 0; i--) {
        if (!TRUSTED.contains(hops.get(i))) return hops.get(i);
    }
    return hops.get(0);
}

public static void main(String[] args) {
    System.out.println(clientIp("10.0.2.7", "203.0.113.9, 10.0.1.5"));
    System.out.println(clientIp("10.0.2.7", "1.2.3.4, 198.51.100.20, 10.0.1.5"));
    System.out.println(clientIp("198.51.100.77", "1.2.3.4"));
}
